// 时间推进兜底 · v4
// 职责一：模型整轮没动 /时间/分钟 时兜底 +30 分钟（时间不倒退、不停摆）。
// 职责二：非法时间结算防御 —— v4 起由 replace 扩到 delta，判据见下方注释。
$(() => {
  const 一周 = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
  const 默认推进分钟 = 30;

  function 推进时间(时间: { 周几: string; 小时: number; 分钟: number } | undefined, 分钟增量: number): boolean {
    if (!时间) return false;
    const 总分钟 = Number(时间.小时 || 0) * 60 + Number(时间.分钟 || 0) + 分钟增量;
    if (!Number.isFinite(总分钟) || 总分钟 < 0) return false;
    const 进位小时 = Math.floor(总分钟 / 60);
    时间.分钟 = 总分钟 % 60;
    时间.小时 = 进位小时 % 24;
    const 跨天 = Math.floor(进位小时 / 24);
    if (跨天 > 0 && 一周.includes(时间.周几)) {
      时间.周几 = 一周[(一周.indexOf(时间.周几) + 跨天) % 7];
    }
    return true;
  }

  waitGlobalInitialized('Mvu').then(() => {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (新变量, 旧变量) => {
      const 最新 = getChatMessages(-1)[0];
      if (!最新 || 最新.role !== 'assistant' || 最新.message_id === 0) return;

      const 新时间 = 新变量?.stat_data?.时间 as { 周几: string; 小时: number; 分钟: number } | undefined;
      const 旧时间 = 旧变量?.stat_data?.时间 as { 周几: string; 小时: number; 分钟: number } | undefined;
      if (!新时间 || !旧时间) return;

      // ===== 非法时间结算防御 =====
      // v4（2026-10-15）：由「只拦 replace」扩到 delta，并按语义分成两种越界——
      //   ① `replace /时间/分钟` 越界（如 602）：模型把「增量」写成了「绝对值」，
      //      MVU 会按分钟进位放大成跨天（周五 20:00 → 周六 06:02）⇒ 整轮回退旧时刻。
      //   ② `delta /时间/分钟` 越界：单看**是合法的**。schema 的 transform 会把
      //      「总分钟 → 进位小时 → 周几」自动进位，实测 delta 792（周五 21:18 → 周六 10:30）
      //      结果完全正确；这里若一律回退，反而会把正确结果打回起点。**只有**同轮还动了
      //      `/时间/小时` 或 `/时间/周几` 时才回退 —— 那才是真正的双跳（分钟推 792，
      //      时刻又被小时/周几覆盖一次，算出来是飞的）。
      const 补丁 = 最新.message.match(/<JSONPatch>([\s\S]*?)<\/JSONPatch>/);
      if (补丁) {
        let 回退 = false;
        try {
          const ops = JSON.parse(补丁[1]) as Array<{ op: string; path: string; value?: unknown }>;
          if (Array.isArray(ops)) {
            const 分钟越界 = (o: { op: string; path: string; value?: unknown }) => {
              const 值 = Number(o.value);
              return o.path === '/时间/分钟' && (!Number.isFinite(值) || 值 < 0 || 值 > 59);
            };
            const 越界项 = ops.filter(分钟越界);
            const 动了小时或周几 = ops.some(o => o.path === '/时间/小时' || o.path === '/时间/周几');
            回退 = 越界项.some(o => o.op === 'replace') || (越界项.length > 0 && 动了小时或周几);
          }
        } catch {
          回退 = false;
        }
        if (回退) {
          _.set(新变量.stat_data, '时间', { ...旧时间 });
          return;
        }
      }

      const 时间未变 =
        新时间.周几 === 旧时间.周几 &&
        Number(新时间.小时) === Number(旧时间.小时) &&
        Number(新时间.分钟) === Number(旧时间.分钟);
      if (时间未变) {
        推进时间(新时间, 默认推进分钟);
      }
    });
  });
});
